#pragma once

// Chudcode icon atlas loader (docs/UI_FOUNDATION.md §6).
//
// Assets are generated by gui/scripts/make_icons.py into gui/assets/icons/:
// two theme atlases (atlas_dark.png / atlas_light.png) share ONE layout
// (atlas.json), so a theme switch swaps textures while every UV stays
// constant. The inventory below is the IDE-domain contract; it must match
// ICON_NAMES in the generator, and loadIcons() refuses an atlas that is
// missing any name at any cell size.
//
// This module never touches GL: texture creation/destruction is injected
// through TextureBackend so the loader is testable headless while still
// owning texture lifetime (unloadIcons destroys everything it uploaded).

#include <array>
#include <functional>
#include <map>
#include <string>

#include <imgui.h>

#include "theme/theme.h"

namespace chud::icons {

// Append-only, mirrors gui/scripts/make_icons.py ICON_NAMES.
inline constexpr std::array<const char*, 20> kIconNames = {
    "send",       "stop",   "attach", "new-session", "close-tab",
    "open-folder", "agent",  "task",   "tool",        "recovery",
    "pin",        "fork",   "rename", "delete",      "git-branch",
    "git-commit", "terminal", "diff", "settings",    "usage",
};

inline constexpr std::array<int, 2> kCellSizes = {20, 32};

struct IconUV {
    ImTextureID texture = 0;
    ImVec2 uv0{0.0f, 0.0f};
    ImVec2 uv1{1.0f, 1.0f};
    float width = 0.0f;   // cell size in atlas pixels
    float height = 0.0f;
    bool valid = false;
};

struct CellRect {
    int x = 0;
    int y = 0;
    int w = 0;
    int h = 0;
};

// Texture creation is injected so chud_icons never links GL and tests run
// headless. upload returns a non-zero ImTextureID for a tightly-packed RGBA8
// image; destroy releases it. The loader stores the backend and owns every
// texture it uploads until unloadIcons().
struct TextureBackend {
    std::function<ImTextureID(const unsigned char* rgba, int width, int height)> upload;
    std::function<void(ImTextureID)> destroy;
};

// Loads <assetsDir>/icons/{atlas.json,atlas_dark.png,atlas_light.png},
// validates the full inventory (every kIconNames × kCellSizes cell present
// and inside the atlas), and uploads both theme textures. Reloading first
// unloads. On failure nothing stays uploaded and *error names the cause.
[[nodiscard]] bool loadIcons(const std::string& assetsDir, TextureBackend backend,
                             std::string* error = nullptr);

// Destroys both theme textures through the stored backend. Safe when not
// loaded. After this every icon() lookup is invalid until the next load.
void unloadIcons();

[[nodiscard]] bool iconsLoaded();

// Call after ui::applyTheme(): swaps which atlas texture icon() hands out.
// UVs are identical across themes by construction.
void setIconTheme(ui::Theme theme);
[[nodiscard]] ui::Theme iconTheme();

// Named lookup. sizePx snaps to the nearest generated cell size (<=26 → 20,
// else 32). Unknown name or unloaded atlas → valid == false (one stderr
// warning per unknown name); drawIcon() still renders an honest fallback.
[[nodiscard]] IconUV icon(const char* name, int sizePx = 20);

// Draws `name` as a sizePx square at pos (top-left) with the given tint
// (identity IM_COL32_WHITE by default: atlases are theme-baked; callers
// re-tint only via semantic palette roles). A missing name renders a
// placeholder — rounded box + diagonal cross in the tint — never a blank.
void drawIcon(ImDrawList* drawList, const char* name, ImVec2 pos, float sizePx,
              ImU32 tint = IM_COL32_WHITE);

// Introspection for tests and asset gates.
[[nodiscard]] const std::map<std::string, CellRect>& iconCells();
[[nodiscard]] ImVec2 atlasSize();

}  // namespace chud::icons
